import { exec } from "node:child_process";
import { createHash } from "node:crypto";
import { access, readdir, symlink, writeFile } from "node:fs/promises";
import { resolve } from "node:path";
import { promisify } from "node:util";

const ENV_FILES = [".env", ".env.development"] as const;
const LOCAL_ENV_FILE = ".env.development.local";

/**
 * The env files live in this package, so both the shared values and the
 * per-worktree overrides resolve from here. Resolve it from this script instead
 * of `process.cwd()` so the hook works from any directory.
 */
const ENV_DIR = resolve(import.meta.dirname, "..");

/** Where the shared files used to live (relative to the main checkout) before the env package was extracted. */
const LEGACY_ENV_DIR = "apps/web";

const PORT_RANGE_START = 9100;
const PORT_RANGE_SIZE = 800;

const EXIT_FAILURE = 1;

const execAsync = promisify(exec);

const gitOutput = async (args: string): Promise<string> =>
  (await execAsync(`git ${args}`, { encoding: "utf-8" })).stdout.trim();

const isGitWorktree = async (): Promise<boolean> => {
  const [gitDir, commonDir] = await Promise.all([
    gitOutput("rev-parse --git-dir"),
    gitOutput("rev-parse --git-common-dir"),
  ]);
  return gitDir !== commonDir;
};

const exists = async (filePath: string): Promise<boolean> => {
  try {
    await access(filePath);
    return true;
  } catch {
    return false;
  }
};

const worktreeHash = (worktreeRoot: string): string =>
  createHash("sha256").update(worktreeRoot).digest("hex");

const localEnvContent = (worktreeRoot: string): string => {
  const hash = worktreeHash(worktreeRoot);
  const port =
    PORT_RANGE_START +
    (Number.parseInt(hash.slice(0, 8), 16) % PORT_RANGE_SIZE);
  const project = `pantry-${hash.slice(0, 8)}`;

  return [
    "# Generated by packages/env/scripts/symlink-env-for-worktree.ts.",
    "# Overrides the shared .env.development so this git worktree can run its own",
    "# libSQL container on a unique host port (see apps/web/compose.yaml).",
    `TURSO_PROJECT=${project}`,
    `TURSO_PORT=${port}`,
    `TURSO_CONNECTION_URL=http://127.0.0.1:${port}`,
    "",
  ].join("\n");
};

const warnMissingSource = async (
  mainRepoRoot: string,
  file: (typeof ENV_FILES)[number],
  source: string
): Promise<void> => {
  const legacySource = resolve(mainRepoRoot, LEGACY_ENV_DIR, file);

  if (await exists(legacySource)) {
    console.warn(
      `Source ${source} not found, but the old ${legacySource} still exists.\n` +
        `Move it to ${source} so every package and worktree reads the same values (see packages/env/README.md).`
    );
    return;
  }

  console.warn(`Source ${source} not found. Skipping ${file}.`);
};

/**
 * Values files that used to live in apps/web. A leftover `apps/web/.env` can
 * point at another libSQL port, so leftovers make the worktree silently diverge
 * from packages/env/.
 */
const isLegacyWorktreeEnvFile = (name: string): boolean =>
  name === ".env" || name.startsWith(".env.development");

const warnLegacyWorktreeEnvFiles = async (
  worktreeRoot: string
): Promise<void> => {
  const legacyDir = resolve(worktreeRoot, LEGACY_ENV_DIR);
  let names: string[];
  try {
    names = await readdir(legacyDir);
  } catch {
    return;
  }

  // readdir also lists dangling symlinks, which `access` would miss.
  const leftovers = names.filter(isLegacyWorktreeEnvFile).toSorted();
  if (leftovers.length === 0) {
    return;
  }

  console.warn(
    `Legacy env files remain in ${legacyDir}: ${leftovers.join(", ")}.\n` +
      "Values now live in packages/env/ and these files can override them (or point at another libSQL port). " +
      "Delete them from this worktree (see packages/env/README.md)."
  );
};

const symlinkSharedEnvFiles = async (mainRepoRoot: string): Promise<void> => {
  for (const file of ENV_FILES) {
    const source = resolve(mainRepoRoot, "packages/env", file);
    const target = resolve(ENV_DIR, file);

    if (!(await exists(source))) {
      await warnMissingSource(mainRepoRoot, file, source);
      continue;
    }

    if (await exists(target)) {
      console.log(`${file} already exists. Skipping.`);
      continue;
    }

    await symlink(source, target);
    console.log(`Symlinked ${target} -> ${source}`);
  }
};

const writeLocalEnvFile = async (worktreeRoot: string): Promise<void> => {
  const target = resolve(ENV_DIR, LOCAL_ENV_FILE);

  if (await exists(target)) {
    console.log(`${LOCAL_ENV_FILE} already exists. Skipping.`);
    return;
  }

  await writeFile(target, localEnvContent(worktreeRoot), "utf-8");
  console.log(`Wrote per-worktree libSQL settings to ${target}`);
};

const main = async (): Promise<void> => {
  if (!(await isGitWorktree())) {
    console.log("Not a git worktree. Skipping.");
    return;
  }

  const [worktreeRoot, commonDir] = await Promise.all([
    gitOutput("rev-parse --show-toplevel"),
    gitOutput("rev-parse --git-common-dir"),
  ]);
  const mainRepoRoot = resolve(worktreeRoot, commonDir, "..");

  await symlinkSharedEnvFiles(mainRepoRoot);
  await writeLocalEnvFile(worktreeRoot);
  await warnLegacyWorktreeEnvFiles(worktreeRoot);
};

try {
  await main();
} catch (error) {
  console.error("Failed to prepare env files:", error);
  process.exit(EXIT_FAILURE);
}
